body:
Seems Ok, but probably better to move invalid tag check to be before these, the invalid tag is interpreted as part of text and should not have any effect.

```diff
diff --git a/scene/gui/rich_text_label.cpp b/scene/gui/rich_text_label.cpp
index a76a43b25a..edf53a5da9 100644
--- a/scene/gui/rich_text_label.cpp
+++ b/scene/gui/rich_text_label.cpp
@@ -4442,6 +4442,15 @@ void RichTextLabel::append_text(const String &p_bbcode) {
 		if (tag.begins_with("/") && tag_stack.size()) {
 			bool tag_ok = tag_stack.size() && tag_stack.front()->get() == tag.substr(1, tag.length());
 
+			if (!tag_ok) {
+				txt += "[" + tag;
+				add_text(txt);
+				after_list_open_tag = false;
+				after_list_close_tag = false;
+				pos = brk_end;
+				continue;
+			}
+
 			if (tag_stack.front()->get() == "b") {
 				in_bold = false;
 			}
@@ -4452,15 +4461,6 @@ void RichTextLabel::append_text(const String &p_bbcode) {
 				current_frame->indent_level--;
 			}
 
-			if (!tag_ok) {
-				txt += "[" + tag;
-				add_text(txt);
-				after_list_open_tag = false;
-				after_list_close_tag = false;
-				pos = brk_end;
-				continue;
-			}
-
 			if (txt.is_empty() && after_list_open_tag) {
 				txt = "\n"; // Make empty list have at least one item.
 			}
```
